WFJ.Data.add("spell", {
  [1214001] = { "Leggi la pergamena per evocare Wrath of the Swarm, che permette alla tua incursione di infliggere fino a $N1 danni e cure in più con gli incantesimi e ne aumenta la potenza d'attacco di $N2 per $D1.", "Potenziato dallo Sciame. Infligge fino a $N1 danni e cure in più con gli incantesimi e ha la potenza d'attacco aumentata di $N2.", 0xaf337261, 0xf2a26529, "uu" },
  [1214004] = { "Applicato all'arma o allo scudo bersaglio, aumenta fino a $N1 i danni degli incantesimi e del $N2% la probabilità di critico degli incantesimi. Dura $N3 min.", nil, 0x75e4b2da, nil, "um" },
  [1214006] = { "Aumenta fino a $N1 i danni e le cure di incantesimi ed effetti magici. Aumenta inoltre la probabilità di colpo critico degli incantesimi del $N2%.", nil, 0x299ae61d, nil, "um" },
  [1214028] = { nil, "Fuga in preda al terrore.", nil, 0xfa67e4a8, "mu" },
  [1214029] = { "Investe un nemico con la magia arcana, infliggendo danni normali e $N1 danni aggiuntivi e respingendolo indietro.", nil, 0x26533b34, nil, "um" },
  [1214037] = { "Sottrae salute a tutti i nemici vicini.", "Sottrae salute a tutti i nemici vicini.", 0x035df0d3, 0x035df0d3, "uu" },
  [1214058] = { "Aumenta del $N1% le cure dei tuoi incantesimi ⟦Holy Light=Luce Sacra⟧ e ⟦Flash of Light=Lampo di Luce⟧.", nil, 0x11a2c394, nil, "um" },
  [1214059] = { "Aumenta del $N1% le cure dei tuoi incantesimi ⟦Chain Heal=Catena di Guarigione⟧ e ⟦Healing Wave=Ondata di Cura⟧.", nil, 0xd4e4189f, nil, "um" },
  [1214063] = { "Aumenta del $N1% le cure dei tuoi incantesimi Bocciolo di Vita, Nutrizione e Crescita Rigogliosa.", nil, 0xae757acd, nil, "um" },
  [1214069] = { "Probabilità, quando colpisci in mischia, di infliggere $N1 danni da fuoco al bersaglio. Infligge danni extra ai Silitidi di ⟦Silithus=Silitus⟧ quasi a ogni colpo.", nil, 0x0d3fc4fc, nil, "um" },
  [1214070] = { "Riduce di $N1 tutti i danni subiti.", "Riduce di $N1 tutti i danni subiti.", 0xa59be9ff, 0xa59be9ff, "uu" },
  [1214085] = { "Riduce del $N1% il tempo di recupero di Dardo del Caos e aumenta del $N2% i danni inflitti da Dardo del Caos e ⟦Shadow Bolt=Dardo d'Ombra⟧. Inoltre, Dardo del Caos ora può attivare il talento ⟦Shadow Bolt=Dardo d'Ombra⟧ Migliorato e gli conferisce $N3 cariche aggiuntive (non si cumula con le cariche aggiuntive di Ombrofuoco).", nil, 0xa77caef7, nil, "um" },
  [1214087] = { "Ogni volta che colpisci un bersaglio con Conflagrazione, ottieni il $N1% di danni da fuoco in più per $D1, cumulabile fino a $N3 volte.", nil, 0x4b1b6584, nil, "um" },
  [1214088] = { nil, "Aumenta del $N1% tutti i danni da fuoco inflitti.", nil, 0x7f6cf186, "mu" },
  [1214091] = { "Riduce di $D1 il tempo di recupero di Fendente d'Ombra.", nil, 0x39dc59b0, nil, "um" },
  [1214095] = { "Gli effetti del tuo Sacrificio Demoniaco ora persistono mentre hai un famiglio demoniaco attivo, purché tu non evochi di nuovo il famiglio sacrificato. Puoi avere attivo un solo effetto di Sacrificio Demoniaco alla volta.", nil, 0xc71dd522, nil, "um" },
  [1214098] = { nil, "Riduce del $N1% i danni fisici subiti.", nil, 0xedb5aac7, "mu" },
  [1214100] = { nil, "Aumenta di $N1 la resistenza a tutte le scuole di magia.", nil, 0x12255ca0, "mu" },
  [1214101] = { nil, "Aumenta del $N1% i danni inflitti.", nil, 0xed9472b4, "mu" },
  [1214102] = { nil, { "Aumenta del $N1% la minaccia generata.", "Riduce del $N1% la minaccia generata.", shape = { "1/0", "1/0" }, key = { "f7928a7b9ab4c9cc", "534cd818be5fd2b0" } }, nil, 0x9f50a38e, "mu" },
  [1214115] = { "Probabilità, quando infliggi danni diretti con un incantesimo, di infliggere $N1 danni da fuoco al bersaglio. Infligge danni extra ai Silitidi di ⟦Silithus=Silitus⟧ quasi a ogni colpo.", nil, 0xd8713e67, nil, "um" },
  [1214125] = { "Probabilità, quando infliggi danni diretti con un incantesimo o con un attacco in mischia, di infliggere $N1 danni da fuoco al bersaglio. Infligge danni extra ai Silitidi di ⟦Silithus=Silitus⟧ quasi a ogni colpo.", nil, 0xe28b5229, nil, "um" },
  [1214136] = { "Dopo $D1, infligge ingenti danni ripartiti fra tutti i bersagli colpiti.", "Dopo $D1, infligge ingenti danni ripartiti fra tutti i bersagli colpiti.", 0x8a6f1acc, 0x8a6f1acc, "uu" },
  [1214143] = { "Probabilità, quando colpisci a distanza, di infliggere $N1 danni da fuoco al bersaglio. Infligge danni extra ai Silitidi di ⟦Silithus=Silitus⟧ quasi a ogni colpo.", nil, 0xfad4d5d6, nil, "um" },
  [1214151] = { "Per $D1 dopo aver usato Fendente d'Ombra, il tuo Dolore Ustionante colpisce $N2 bersaglio aggiuntivo entro la portata da mischia.", nil, 0x6eaf27b8, nil, "um" },
  [1214155] = { "Aumenta del $N1% per ogni pezzo di armatura Timeworn indossato i danni inflitti da tutti i tuoi incantesimi di danno nel tempo.", nil, 0x4e9d6f1a, nil, "um" },
  [1214156] = { nil, "Il tuo Dolore Ustionante colpisce $N1 bersagli aggiuntivi entro la portata da mischia.", nil, 0x6d561b0d, "mu" },
  [1214157] = { "Cura il bersaglio di $N1.", nil, 0xbdf1d263, nil, "um" },
  [1214158] = { "Purificazione cura inoltre il bersaglio di $N1.", nil, 0x07fde7c4, nil, "um" },
  [1214159] = { "Riduce del $N1% il tempo di recupero di Desiderio di Morte.", nil, 0xe5e424bf, nil, "um" },
  [1214160] = { "Riduce del $N1% il tempo di recupero di ⟦Thunder Clap=Schianto del Tuono⟧.", nil, 0x86b2cd64, nil, "um" },
  [1214162] = { "Il tuo ⟦Shield Slam=Colpo di Scudo⟧ genera il $N1% di minaccia in più e il suo tempo di recupero si azzera se viene schivato, parato o bloccato.", nil, 0xcc42f8b6, nil, "um" },
  [1214163] = { "Infliggi il $N1% di danni in più mentre un nemico vicino è afflitto sia dal tuo Squartamento sia dalle tue ⟦Deep Wounds=Ferite Profonde⟧.", nil, 0xb6437908, nil, "um" },
  [1214165] = { "Riduce del $N1% il tempo di recupero di Onda d'Urto.", nil, 0x8c060c65, nil, "um" },
  [1214166] = { nil, "Aumenta del $N1% tutti i danni inflitti.", nil, 0xbb0dd240, "mu" },
  [1214168] = { "Ricopre un'arma con un veleno che dura $N1 min.\nOgni colpo ha una probabilità del $N2% di avvelenare il nemico, infliggendo $N3 danni da natura in $D1 e facendogli subire il $N5% di danni da arcano, da fuoco, da gelo, da natura e da ombra in più. Si accumula fino a $N6 volte sullo stesso bersaglio.\n\nOccult Poison conta come ⟦Deadly Poison=Veleno Mortale⟧ e beneficia di tutti i talenti e gli effetti che si attivano con ⟦Deadly Poison=Veleno Mortale⟧ o lo modificano.", nil, 0x88540c3c, nil, "um" },
  [1214169] = { "Ti insegna l'abilità Occult Poison (Grado $N1).", nil, 0x212a53fa, nil, "um" },
  [1214170] = { nil, "Il bersaglio subisce $N1 danni da natura ogni $N2 s e il $N3% di danni da arcano, da fuoco, da gelo, da natura e da ombra in più.", nil, 0x4290b92c, "mu" },
  [1214171] = { "Ricopre un'arma con un veleno che dura $N1 min. Ogni colpo ha una probabilità del $N2% di avvelenare il nemico, infliggendo $N3 danni da natura in $D1 e facendogli subire il $N5% di danni da arcano, da fuoco, da gelo, da natura e da ombra in più. Si accumula fino a $N6 volte sullo stesso bersaglio.\n\nOccult Poison conta come ⟦Deadly Poison=Veleno Mortale⟧ e beneficia di tutti i talenti e gli effetti che si attivano con ⟦Deadly Poison=Veleno Mortale⟧ o lo modificano.", nil, 0xdb56e997, nil, "um" },
  [1214179] = { "Ti trasformi in un mezzorso per $D1.", "Trasformato in un mezzorso.", 0x9565f3ee, 0x105a6e3d, "uu" },
  [1214204] = { "Aumenta fino a $N1 le cure e fino a $N2 i danni prodotti da incantesimi ed effetti magici.", nil, 0x77ff472e, nil, "um" },
  [1214205] = { "Disorienta il bersaglio, costringendolo a vagare senza meta per un massimo di $D1.", "Disorientato.", 0xfb3cce19, 0x6b902ba7, "uu" },
  [1214206] = { "Evoca dei Vanquished Tentacles sopra il bersaglio, che lo inseguono e lo attaccano per $D1.", nil, 0x8faa94e9, nil, "um" },
  [1214208] = { "Sottrae $N1 salute al bersaglio nemico.", nil, 0x8e44b266, nil, "um" },
  [1214214] = { "Fa cadere una meteora che brucia tutti i nemici nell'area, infliggendo $N1 danni da fuoco in totale e stordendoli per $D1.", nil, 0x5a53e356, nil, "um" },
  [1214223] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [1214233] = { "Aumenta fino a $N1 i danni inflitti da incantesimi ed effetti magici e riduce di $N2 le resistenze magiche dei bersagli dei tuoi incantesimi per $D1.", "Danni magici aumentati fino a $N1.\nResistenze magiche dei bersagli dei tuoi incantesimi ridotte di $N2.", 0xb0176327, 0xe014e8ba, "uu" },
  [1214258] = { "Quando colpisci in mischia o a distanza, ottieni $N1 mana e, se possibile, prosciughi $N2 mana dal bersaglio.", nil, 0x4ea4561c, nil, "um" },
  [1214263] = { "Aculei fuoriescono dal tuo corpo, infliggendo $N1 danni da natura agli attaccanti all'impatto. Dura $D1.", "$N1 danni da natura inflitti agli attaccanti.", 0x5c2e53ce, 0x7724a9e2, "uu" },
  [1214272] = { "Quando un incantesimo dannoso ti colpisce, chi lo ha lanciato ha una probabilità del $N1% di essere silenziato per $D1.", nil, 0xc50503b8, nil, "um" },
  [1214273] = { "Silenzia un nemico, impedendogli di lanciare incantesimi per $D1.", "Impossibile lanciare incantesimi.", 0x444e4a7e, 0x6d133d61, "uu" },
  [1214276] = { "Riduce i danni magici subiti di $N1.", nil, 0x1d9ea266, nil, "um" },
  [1214278] = { "Aumenta la potenza d'attacco in mischia e a distanza di $N1 per $D1.", "Potenza d'attacco in mischia e a distanza aumentata di $N1.", 0xf1ea894a, 0x558973f8, "uu" },
